import csv

# Zones and the sensors we found in the graph
zones_sensors = {
    "Zone_F3_Z01": "http://buildgraph.org/BG_large_office_2004_0000#VAV_F3_Z01.Zone_Air_Temperature_Sensor",
    "Zone_F3_Z02": "http://buildgraph.org/BG_large_office_2004_0000#VAV_F3_Z02.Zone_Air_Temperature_Sensor",
    "Zone_F3_Z04": "http://buildgraph.org/BG_large_office_2004_0000#VAV_F3_Z04.Zone_Air_Temperature_Sensor",
    "Zone_F3_Z05": "http://buildgraph.org/BG_large_office_2004_0000#VAV_F3_Z05.Zone_Air_Temperature_Sensor",
}

target_timestamp = "2018-10-09T11:00:00"

# 1. To handle the naming discrepancy, let's find all sensors in the catalog that are "Zone_Air_Temperature_Sensor"
# and see if they match our zones.
sensor_to_tsid = {}
with open(CATALOG_CSV, 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        uri = row['point_uri']
        # Match either the VAV name or the Zone name
        for zone, graph_sensor_uri in zones_sensors.items():
            if uri == graph_sensor_uri or uri == f"http://buildgraph.org/BG_large_office_2004_0000#{zone}.Zone_Air_Temperature_Sensor":
                sensor_to_tsid[uri] = row['timeseries_id']

print(f"Sensor to TSID found: {sensor_to_tsid}")

# 2. Map TSID back to Zone
tsid_to_zone = {}
with open(CATALOG_CSV, 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        uri = row['point_uri']
        tsid = row['timeseries_id']
        for zone, graph_sensor_uri in zones_sensors.items():
            if uri == graph_sensor_uri or uri == f"http://buildgraph.org/BG_large_office_2004_0000#{zone}.Zone_Air_Temperature_Sensor":
                tsid_to_zone[tsid] = zone

print(f"TSID to Zone: {tsid_to_zone}")

# 3. Get values at timestamp
found_values = []
with open(VALUES_CSV, 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['timestamp'] == target_timestamp:
            tsid = row['timeseries_id']
            if tsid in tsid_to_zone:
                zone = tsid_to_zone[tsid]
                found_values.append((zone, float(row['value'])))

print(f"Values at {target_timestamp}: {found_values}")

